def priority(task, state, m=5.0, b=0.6, c=1.0, cap=6.0):
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    wait = max(0.0, state.now - task.release)
    mean = max(state.mean_est, 1e-6)
    age = max(0.0, wait / mean - c)
    if age > cap:
        age = cap
    return tier / est * (1.0 + b * age)

def priority(task, state, m=5.0, a=0.7, k=2.0, b=0.25, cap=5.0):
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
