def priority(task, state, b=0.5, t=1.0, m=1.5, g=0.6, k=4.0):
    r = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    mean = max(state.mean_est, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    pressure = state.queue_work / max(state.capacity * mean, 1e-6)
    late = max(0.0, state.now + r - task.due)
    slack = max(0.0, task.due - state.now - r)
    if pressure >= t:
        return tier * task.weight / r * (1.0 + g * late / mean)
    else:
        return tier * task.weight / r * (1.0 + b * wait / r) * math.exp(-slack / max(k * mean, 1e-6))

