import math
def priority(task, state, m=5.0, c=2.0, a=1.5, q=10.0, g=1e6, u=0.5, d=0.5):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    ratio = wait / est
    tier = m if task.tenant == 'premium' else 1.0
    if task.tenant == 'premium':
        guard = g if ratio >= c else 0.0
    else:
        guard = g if ratio >= c * 2.0 and state.queue_len > q else 0.0
    slack = max(0.0, task.due - state.now - est)
    urg = math.exp(-slack / max(state.mean_est, 1e-6))
    return guard + (tier / est) * (1.0 + a * max(0.0, ratio - d) + u * urg)

