import math
def priority(task, state, b=1.0, m=3.0, free_th=0.25, k=3.0, pack=0.7):
    eps = 1e-6
    e = max(task.estimated_runtime, eps)
    mean = max(state.mean_est, eps)
    wait = max(0.0, state.now - task.release)
    tier = m if task.tenant == 'premium' else 1.0
    base = tier * max(task.weight, eps) / e * (1.0 + b * wait / e)
    free_ratio = state.free / max(state.capacity, eps)
    if free_ratio < free_th:
        mem_ratio = min(task.resource_need / max(state.capacity, eps), 1.0)
        return base * (1.0 + pack * (1.0 - mem_ratio) / max(free_ratio, eps))
    else:
        slack = max(0.0, task.due - state.now - task.estimated_runtime)
        return base * (1.0 + math.exp(-slack / max(k * mean, eps)))

